class Store:
    def __init__(self):
        self._data = {}

    def open_window(self, key, now, window):
        self._data[key] = {"count": 1, "expires_at": now + window}

    def all_items(self):
        return list(self._data.items())

    def drop(self, key):
        self._data.pop(key, None)

