import config
from store import Store

_STORE = Store()

def sweep(now):
    """Drop keys whose window has expired at or before `now`."""
    stale = [k for k, v in _STORE.all_items() if v["expires_at"] < now]
    for k in stale:
        _STORE.drop(k)
